def pct(x):return '—' if pd.isna(x) else f'{100*x:.2f}%'
def num(x):return '—' if pd.isna(x) else f'{int(x):,}'.replace(',',' ')
def pval(x):return '—' if pd.isna(x) else (f'{x:.2g}' if x<.001 else f'{x:.4f}')
def table(df):return df.to_html(index=False,escape=True,border=0,na_rep='—',classes='data')
def htable(h,groups=None):
 g=hr[(hr.hypothesis==h)&hr.split.isin(['historical','validation_post_H18'] if h=='H18' else ['historical','validation'])].copy()
 if groups is not None:g=g[g.group.isin(groups)]
 if g.empty:return ''
 def label(s):
  fixed={'after_unexpected_SAVE':'После неожиданного SAVE','after_unexpected_GOAL':'После неожиданного GOAL','after_error':'После ошибки фаворита','after_hit':'После победы фаворита','GOAL_1.10_to_1.15_ALL_sectors_proxy':'GOAL 1,10–1,15, все сектора'}
  if s in fixed:return fixed[s]
  if s.startswith('sector_'):return 'Сектор '+s.removeprefix('sector_')
  if s.startswith('favorite_odds_'):return 'Цена фаворита '+s.removeprefix('favorite_odds_').replace('_to_','–')
  if s.startswith('preceding_run_at_least_'):return 'Предыдущая серия ≥'+s.rsplit('_',1)[-1]
  return s
 out=pd.DataFrame({'Выборка':g.split.map({'historical':'V11–V12','validation':'V13 ≥29.10','validation_post_H18':'V13 ≥30.10'}),'Группа':g.group.map(label),'n':g.n.map(num),'Побед':g.wins.map(num),'Факт':g.win_rate.map(pct),'Ожидание':g.mean_p.map(pct),'Разница, п.п.':g.gap.map(lambda x:f'{100*x:+.2f}' if pd.notna(x) else '—'),'ROI':g.roi.map(pct),'95% ДИ ROI':g.roi_ci.map(lambda x:'—' if pd.isna(x) else ' … '.join(pct(z) for z in ast.literal_eval(x)))})
 return table(out)
def ctable():
 g=co.copy();g=g[g.cohort.isin(['historical','retrospective_holdout','strict_5sec','ws_verified','strict_15sec'])];return table(pd.DataFrame({'Выборка':g.cohort,'n':g.n.map(num),'Доля GOAL':g.goal_rate.map(pct),'Прогноз GOAL':g.p_goal_mean.map(pct),'Overround':g.mean_overround.map(pct),'p калибровки':g.cluster_p.map(pval)}))
def tests_for(h):
 g=ht[ht.hypothesis.eq(h)&ht.split.isin(['validation','validation_post_H18'])];return '; '.join(f'{r.test}: p={pval(r.p)}, Holm={pval(r.p_holm_all_validation_tests)}' for r in g.itertuples())
