statuses=[('H01','После неожиданного SAVE следующий фаворит сильнее прогноза','Не подтверждено на проверочной части'),('H02','После неожиданного GOAL аналогичного эффекта нет','Убедительного эффекта нет; эквивалентность не доказана'),('H03','После ошибки и попадания различаются отклонения от прогноза','Не подтверждено'),('H04','Серия двух/трёх ошибок влияет на следующего фаворита','Не подтверждено; длинные серии малы'),('H05','Серии правильных прогнозов не дают преимущества','Преимущество не обнаружено; длины 5–6 невозможны внутри матча'),('H06','Коэффициенты 1,00–1,19 выигрывают чаще рынка','Да относительно пропорциональной модели; неустойчиво к снятию маржи'),('H07','Серия низких коэффициентов влияет на следующий исход','Не подтверждено'),('H08','История двух цен улучшает прогноз следующего удара','Улучшение на проверочной части не обнаружено'),('H09','Частота GOAL различается по секторам','Поддержано для сектора UI; существенная часть учтена ценой'),('H10','Результаты зависят от конкретного вратаря','Недостаточная достоверность привязки'),('H11','Взаимодействие вратарь × сектор сверх цены','Не поддаётся надёжной проверке с текущими keeper-links'),('H12','Центр и GOAL≈1,13 означают известный исход','Не проверено: нет геометрии секторов и видеомоментов'),('H13','Расписание вратарей частично циклическое','Исторический четырёхименной цикл найден, позднее не воспроизведён'),('H14','Повторяются длинные заранее снятые видео','Не доказано; видеоотпечатков нет'),('H15','GOAL/SAVE появляется до вылета мяча','Не проверено без видеовремени'),('H16','Коэффициенты появляются после выбора сектора','Описано правилами; не измерено сборщиком независимо'),('H17','Длительные паузы приёма при продолжающемся видео','Журналы не подтверждают наблюдение; видео и цензурирование не измерены'),('H18','SAVE ровно 1,22 сильнее GOAL ровно 1,22','Не подтверждено; на поздней части направление обратное')]
